      "content": "{\n  \"name\": \"cc-safety-net\",\n  \"version\": \"2.6.19\",\n  \"description\": \"A coding agent CLI hook - block destructive commands and secret file access\",\n  \"keywords\": [\n    \"amp\",\n    \"claude-code\",\n    \"cursor\",\n    \"deepseek-harness\",\n    \"devin\",\n    \"devin-cli\",\n    \"droid\",\n    \"factory-droid\",\n    \"grok\",\n    \"grok-build\",\n    \"opencode\",\n    \"pi-package\",\n    \"plugin\",\n    \"safety\",\n    \"security\"\n  ],\n  \"homepage\": \"https://ccsafetynet.com\",\n  \"bugs\": {\n    \"url\": \"https://github.com/kenryu42/cc-safety-net/issues\"\n  },\n  \"license\": \"MIT\",\n  \"author\": {\n    \"name\": \"J Liew\",\n    \"email\": \"jliew@420024lab.com\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/kenryu42/cc-safety-net.git\"\n  },\n  \"bin\": {\n    \"cc-safety-net\": \"dist/bin/cc-safety-net.js\",\n    \"ccsn\": \"dist/bin/cc-safety-net.js\"\n  },\n  \"files\": [\n    \"dist\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./api\": {\n      \"types\": \"./dist/api.d.ts\",\n      \"import\": \"./dist/api.js\"\n    },\n    \"./opencode/v2\": {\n      \"types\": \"./dist/opencode-v2.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"scripts\": {\n    \"audit:dependencies\": \"bun audit --ignore=GHSA-ch52-4w7c-c8xp\",\n    \"build\": \"bun run clean && bun scripts/project-bun.ts scripts/build.ts\",\n    \"build:plugin\": \"bun scripts/project-bun.ts scripts/build-plugin-tree.ts\",\n    \"build:types\": \"tsc --project tsconfig.build.json --emitDeclarationOnly --declaration\",\n    \"verify:package\": \"bun run scripts/verify-package.ts\",\n    \"verify:repository-plugin\": \"bun run scripts/verify-repository-plugin.ts\",\n    \"verify:coverage\": \"bun run scripts/verify-coverage.ts\",\n    \"clean\": \"rm -rf dist\",\n    \"check\": \"bun run lint && bun run lint:comments && bun run format:check && bun run typecheck && bun run knip && bun run check-duplicates && bun run test:coverage && bun run verify:coverage\",\n    \"check:ci\": \"bun run check\",\n    \"lint\": \"oxlint src tests scripts knip.ts\",\n    \"lint:ci\": \"bun run lint && bun run format:check\",\n    \"lint:comments\": \"bun scripts/check-comments.ts\",\n    \"typecheck\": \"tsc --noEmit && tsc -p tsconfig.gui.json --noEmit\",\n    \"knip\": \"knip-bun --production\",\n    \"check-duplicates\": \"jscpd src tests --threshold 0 --exit-code 1 --no-tips --reporters ai --ignore '**/*.svg' --ignore-pattern 'import\\\\s[\\\\s\\\\S]*?from\\\\s[^;]*;'\",\n    \"test\": \"bun test --timeout 30000\",\n    \"test:e2e:stability\": \"bun test tests/e2e --timeout 30000 --randomize --rerun-each 3\",\n    \"test:e2e:live\": \"CC_SAFETY_NET_E2E_LIVE=1 bun test tests/e2e-live\",\n    \"test:coverage\": \"AGENT=1 bun test tests --timeout 30000 --path-ignore-patterns 'tests/e2e-live/**' --coverage --coverage-reporter=text --coverage-reporter=lcov\",\n    \"cc-safety-net\": \"bun run src/entries/bin.ts\",\n    \"gui:dev\": \"bun scripts/gui-dev.ts\",\n    \"eval\": \"claude plugin eval . --ablation with-without --judge-model sonnet --allow-tools \\\"Bash(npx -y cc-safety-net:*)\\\" \\\"Bash(npx cc-safety-net:*)\\\"\",\n    \"prepare\": \"lefthook install\",\n    \"lint:fix\": \"oxlint --fix src tests scripts knip.ts\",\n    \"format\": \"oxfmt src tests scripts knip.ts .oxfmtrc.json .oxlintrc.json package.json kimi.plugin.json tsconfig.json tsconfig.build.json tsconfig.gui.json .claude-plugin .codex-plugin .cursor-plugin assets/cc-safety-net.schema.json docs/residual-risk-registry.json hooks\",\n    \"format:check\": \"oxfmt --check src tests scripts knip.ts .oxfmtrc.json .oxlintrc.json package.json kimi.plugin.json tsconfig.json tsconfig.build.json tsconfig.gui.json .claude-plugin .codex-plugin .cursor-plugin assets/cc-safety-net.schema.json docs/residual-risk-registry.json hooks\"\n  },\n  \"devDependencies\": {\n    \"@ampcode/plugin\": \"0.0.0-20260724002649-ga3413e7\",\n    \"@opencode-ai/plugin\": \"^1.18.29\",\n    \"@opencode/plugin\": \"2.0.6\",\n    \"@opencode/schema\": \"2.0.6\",\n    \"@types/bun\": \"latest\",\n    \"effect\": \"4.0.0-rc.112\",\n    \"jscpd\": \"^5.0.14\",\n    \"knip\": \"^6.32.0\",\n    \"lefthook\": \"^2.1.10\",\n    \"oxc-parser\": \"0.142.0\",\n    \"oxfmt\": \"0.70.0\",\n    \"oxlint\": \"1.85.0\",\n    \"oxlint-tsgolint\": \"7.0.2002\",\n    \"typescript\": \"7.0.2\"\n  },\n  \"peerDependencies\": {\n    \"@opencode-ai/plugin\": \"^1.18.29\",\n    \"@opencode/plugin\": \"^2.0.6\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@opencode-ai/plugin\": {\n      \"optional\": true\n    },\n    \"@opencode/plugin\": {\n      \"optional\": true\n    }\n  },\n  \"overrides\": {\n    \"@opentelemetry/core\": \"2.8.0\",\n    \"ip-address\": \"^10.7.4\",\n    \"js-yaml\": \"^4.3.1\",\n    \"picomatch@^2.3.1\": \"2.3.2\",\n    \"picomatch@^4.0.1\": \"^4.0.5\",\n    \"smol-toml\": \"^1.9.0\",\n    \"toml\": \"^5.0.1\",\n    \"undici@^6\": \"^6.29.1\",\n    \"undici@^8\": \"^8.12.2\",\n    \"yaml\": \"^2.9.0\",\n    \"zod\": \"^4.6.6\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"packageManager\": \"bun@1.4.2\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./dist/deepseek-harness/cordis.patch.yml\"\n    }\n  },\n  \"pi\": {\n    \"extensions\": [\n      \"./dist/pi/index.js\"\n    ]\n  }\n}\n"
